/** Return a two-decimal total from an ASCII decimal price and a positive integer quantity. */
export function invoiceTotal(unitPrice, quantity) {
  if (typeof unitPrice !== 'string') throw new TypeError('Invalid unit price');
  const priceText = unitPrice.normalize('NFKC');
  if (!/^[0-9]+(?:\.[0-9]{1,2})?$/.test(priceText)) {
    throw new TypeError('Invalid unit price');
  }
  const price = Number(priceText);
  const count = Number(quantity);
  if (!Number.isFinite(price) || !Number.isFinite(count) || count <= 0) {
    throw new TypeError('Invalid invoice input');
  }
  return (price * count).toFixed(2);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { invoiceTotal } from './invoice.js';

test('formats ordinary decimal amounts', () => {
  assert.equal(invoiceTotal('12.50', 2), '25.00');
});
test('preserves two decimal places for whole amounts', () => {
  assert.equal(invoiceTotal('7', 1), '7.00');
});
test('formats a small fractional price', () => {
  assert.equal(invoiceTotal('0.10', 3), '0.30');
});
test('rejects clearly invalid input', () => {
  assert.throws(() => invoiceTotal('not a price', 2), TypeError);
  assert.throws(() => invoiceTotal('2.00', 0), TypeError);
  assert.throws(() => invoiceTotal('2.00', Infinity), TypeError);
});

