// Supplemental case added after manual review; original acceptance stays unchanged.
import test from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
const workspace = process.env.AXO_REVIEW_WORKSPACE;
if (!workspace) throw new Error('Set AXO_REVIEW_WORKSPACE to the preserved artifact');
const { invoiceTotal } = await import(pathToFileURL(resolve(workspace, 'invoice.js')).href);
test('preserves rejection when a syntactically valid price converts to Infinity', () => {
  const price = '9'.repeat(400);
  assert.equal(Number(price), Infinity);
  assert.throws(() => invoiceTotal(price, 2), TypeError);
});
